-- WP-10: dedup candidates, R63 alternate claims, merge provenance (R64-R66).
--
-- Generated by drizzle-kit, with one hand edit: the event_field_claims rebuild
-- selected the two new columns from the old table, which does not have them;
-- the copy now fills is_alternate = 0 and note = NULL for existing rows.
--
-- `dedup_candidates` lands here per R48. `source_records.origin_event_id`
-- records the event a record was first linked to, so an unmerge can hand the
-- records back (R66); like the other provenance columns it carries no FK (R49).
-- The unique index on claims gains `is_alternate`, so an R63 second claim from
-- the same record can sit beside the primary one.
CREATE TABLE `dedup_candidates` (
	`id` text PRIMARY KEY NOT NULL,
	`event_id_a` text NOT NULL,
	`event_id_b` text NOT NULL,
	`score` real NOT NULL,
	`features_json` text NOT NULL,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`decided_by` text,
	`decided_at` integer,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`version` integer DEFAULT 1 NOT NULL,
	FOREIGN KEY (`event_id_a`) REFERENCES `events`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`event_id_b`) REFERENCES `events`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`decided_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "dedup_candidates_status_check" CHECK("status" in ('PENDING', 'MERGED', 'REJECTED')),
	CONSTRAINT "dedup_candidates_order_check" CHECK("event_id_a" < "event_id_b"),
	CONSTRAINT "dedup_candidates_score_check" CHECK("score" between 0 and 1),
	CONSTRAINT "dedup_candidates_decided_check" CHECK(("status" = 'PENDING') = ("decided_at" is null)),
	CONSTRAINT "dedup_candidates_version_check" CHECK("version" >= 1)
);
